INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1548677, 203517, 35545, '<td valign="top">I know I''m picky, but that''s leather, not rawhinde.  The texture is OK.</td>', 'I know I''m picky, but that''s leather, not rawhinde.  The texture is OK.', '2005-07-20 01:54:48.000000', NULL, 1),
(1548678, 206073, 37103, '<td valign="top">Everything looks so crisp.  Stylistically I might have liked to see the red and yellow divided by one of the green vegetables.  Very good interpretation of texture.</td>', 'Everything looks so crisp.  Stylistically I might have liked to see the red and yellow divided by one of the green vegetables.  Very good interpretation of texture.', '2005-07-20 01:54:49.000000', NULL, 1),
(1548679, 206495, 37252, '<td valign="top">OOF - right inner edge of quartz looks over-sharpened. Need to increase DOF</td>', 'OOF - right inner edge of quartz looks over-sharpened. Need to increase DOF', '2005-07-20 01:55:14.000000', NULL, 1),
(1548680, 206305, 35545, '<td valign="top">Wow.</td>', 'Wow.', '2005-07-20 01:55:16.000000', NULL, 1),
(1548681, 206429, 40855, '<td valign="top">Great subject (i''ll admit to a weakness for rusty metal) and the photo is almost very good, IMO, except that you DOF is a bit too small. I would have liked to see more of the wire in focus. Also the part that is in focus is too dark. Plus the composition/cropping could be improved. But nice nonetheless.</td>', 'Great subject (i''ll admit to a weakness for rusty metal) and the photo is almost very good, IMO, except that you DOF is a bit too small. I would have liked to see more of the wire in focus. Also the part that is in focus is too dark. Plus the composition/cropping could be improved. But nice nonetheless.', '2005-07-20 01:55:27.000000', NULL, 1),
(1548683, 205884, 39755, '<td valign="top">Metallica!</td>', 'Metallica!', '2005-07-20 01:55:39.000000', NULL, 1),
(1548684, 205730, 7570, '<td valign="top">the tones on the trunk and the hill in the backgroundis pleasing and fits the mood. the textture on the tree and the shape of the roots are very interesting and captures my attention. however, the weird sky colour is highly distracting. a softer shade of blue (not cyan) would have made me give you a higher score. anyway, overall a nice shot.</td>', 'the tones on the trunk and the hill in the backgroundis pleasing and fits the mood. the textture on the tree and the shape of the roots are very interesting and captures my attention. however, the weird sky colour is highly distracting. a softer shade of blue (not cyan) would have made me give you a higher score. anyway, overall a nice shot.', '2005-07-20 01:55:40.000000', NULL, 1),
(1548686, 204188, 259, '<td valign="top">too bad you can''t burn in open challenges.  the light on his coat is pulling attention away from his face.</td>', 'too bad you can''t burn in open challenges.  the light on his coat is pulling attention away from his face.', '2005-07-20 01:55:52.000000', NULL, 1),
(1548688, 204769, 15711, '<td valign="top">Great macro.  The lighting seems a tad harsh. Maybe due to the time of day. I like the contrast of green ahd the purple/white. Great for the challenge.</td>', 'Great macro.  The lighting seems a tad harsh. Maybe due to the time of day. I like the contrast of green ahd the purple/white. Great for the challenge.', '2005-07-20 01:56:07.000000', NULL, 1),
