(1550202, 206557, 37719, '<td valign="top">The lighting placement could have been better - the glare is distracting.</td>', 'The lighting placement could have been better - the glare is distracting.', '2005-07-20 12:59:14.000000', NULL, 1),
(1550204, 205272, 36936, '<td valign="top">To dark.</td>', 'To dark.', '2005-07-20 12:59:38.000000', NULL, 1),
