(1551186, 205993, 27158, '<td valign="top">good focus, exposure and composition. Color good and nice background. textures not especially striking, but nice pic.</td>', 'good focus, exposure and composition. Color good and nice background. textures not especially striking, but nice pic.', '2005-07-20 18:59:44.000000', NULL, 1),
(1551187, 206557, 33947, '<td valign="top">Clever idea. Made me smile. The wood background is a little disappointing, though. From the black I can see on the sides, I think a solid black background would have been teriffic!</td>', 'Clever idea. Made me smile. The wood background is a little disappointing, though. From the black I can see on the sides, I think a solid black background would have been teriffic!', '2005-07-20 19:00:22.000000', NULL, 1),
(1551189, 203466, 35947, '<td valign="top">Pretty scene.  Looks grainy/pixelly on my screen though.  Honestly not feeling "texture" here.</td>', 'Pretty scene.  Looks grainy/pixelly on my screen though.  Honestly not feeling "texture" here.', '2005-07-20 19:00:52.000000', NULL, 1),
(1551190, 206495, 27158, '<td valign="top">very nice textures and colors. exposure seems good, but focus seems a bit soft. composition could be better, imo, but nice photo</td>', 'very nice textures and colors. exposure seems good, but focus seems a bit soft. composition could be better, imo, but nice photo', '2005-07-20 19:01:57.000000', NULL, 1),
(1551194, 203529, 27158, '<td valign="top">this would be so much better if the foreground oof elements had been removed. Otherwise, good focus and color. I like the composition and the textures are good</td>', 'this would be so much better if the foreground oof elements had been removed. Otherwise, good focus and color. I like the composition and the textures are good', '2005-07-20 19:04:31.000000', NULL, 1),
(1551197, 205322, 27158, '<td valign="top">this has all the makings of a really fine photograph. it meets the challenge very well, is nicely composed and the exposure is good. Too bad about the very bright orange center of attraction being out of focus.</td>', 'this has all the makings of a really fine photograph. it meets the challenge very well, is nicely composed and the exposure is good. Too bad about the very bright orange center of attraction being out of focus.', '2005-07-20 19:06:34.000000', NULL, 1),
(1551202, 205736, 27158, '<td valign="top">good texture! the image is a bit flat to me and could use a kick in contrast and saturation. nice composition, focus and exposure. bumping up</td>', 'good texture! the image is a bit flat to me and could use a kick in contrast and saturation. nice composition, focus and exposure. bumping up', '2005-07-20 19:09:17.000000', NULL, 1),
(1551207, 205986, 27158, '<td valign="top">image too small to evaluate well. Looks a bit soft focus...not much texture visible. overall seems a bit flat. composition ok, not very strong</td>', 'image too small to evaluate well. Looks a bit soft focus...not much texture visible. overall seems a bit flat. composition ok, not very strong', '2005-07-20 19:11:17.000000', NULL, 1),
(1551213, 206515, 27158, '<td valign="top">lots of nice textures here and the b/w is fine. the highlight seems a bit blown and the light areas on the right margine are distracting. composition is ok.</td>', 'lots of nice textures here and the b/w is fine. the highlight seems a bit blown and the light areas on the right margine are distracting. composition is ok.', '2005-07-20 19:13:18.000000', NULL, 1),
(1551214, 205532, 40762, '<td valign="top">my personal favorite</td>', 'my personal favorite', '2005-07-20 19:13:28.000000', NULL, 1),
(1551218, 203940, 27158, '<td valign="top">texture is not this image''s strong point. composition is good, focus is soft, exposure is fine.</td>', 'texture is not this image''s strong point. composition is good, focus is soft, exposure is fine.', '2005-07-20 19:15:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1551220, 206414, 40370, '<td valign="top">I like that the cat caught my eye at the very last second, nice surprise. Love the multiple textures.<br/><br/><i>Message edited by author 2005-07-28 17:20:41.</i></td>', 'I like that the cat caught my eye at the very last second, nice surprise. Love the multiple textures.', '2005-07-20 19:18:02.000000', '2005-07-28 18:20:41.000000', 1),
(1551221, 206261, 27158, '<td valign="top">nice, crisp focus and detail. i see more line than texture. i think the background is distracting, being such a strong color in relation to the muted greens. a lovely photograph though...bumping up</td>', 'nice, crisp focus and detail. i see more line than texture. i think the background is distracting, being such a strong color in relation to the muted greens. a lovely photograph though...bumping up', '2005-07-20 19:18:24.000000', NULL, 1),
(1551224, 204906, 40370, '<td valign="top">Beautiful color on the lizard but the background coloring is harsh.</td>', 'Beautiful color on the lizard but the background coloring is harsh.', '2005-07-20 19:19:57.000000', NULL, 1),
(1551225, 204802, 34194, '<td valign="top">you''re on a roll....</td>', 'you''re on a roll....', '2005-07-20 19:20:48.000000', NULL, 1),
(1551226, 206466, 27158, '<td valign="top">nice exposure and focus - although i would really have liked to have seen the whole image in focus...either that of lose the back  berries. nice textures set off by the white, smooth background</td>', 'nice exposure and focus - although i would really have liked to have seen the whole image in focus...either that of lose the back  berries. nice textures set off by the white, smooth background', '2005-07-20 19:20:57.000000', NULL, 1),
(1551229, 206574, 27158, '<td valign="top">although the background does give a feeling of place, I find it distracting and think the composition could have been stronger with that in mind. the main focal point is well focused and exposed. nice textures and side-lighting is effective in that regard</td>', 'although the background does give a feeling of place, I find it distracting and think the composition could have been stronger with that in mind. the main focal point is well focused and exposed. nice textures and side-lighting is effective in that regard', '2005-07-20 19:23:24.000000', NULL, 1),
(1551236, 203429, 27158, '<td valign="top">very interesting composition! While is see more line than texture here, i really like the photo. lighting from side is effective and focus is good. nice shot!</td>', 'very interesting composition! While is see more line than texture here, i really like the photo. lighting from side is effective and focus is good. nice shot!', '2005-07-20 19:26:05.000000', NULL, 1),
(1551237, 205736, 40370, '<td valign="top">Nice tight shot, a little bright on the top though, and it seems his coloring gives the appearance of texture rather than light and shadowing.</td>', 'Nice tight shot, a little bright on the top though, and it seems his coloring gives the appearance of texture rather than light and shadowing.', '2005-07-20 19:26:13.000000', NULL, 1),
(1551247, 204224, 27158, '<td valign="top">really nice shot. colors are strong, focus very good and composition interesting. the oof part up-per right is slightly distracting, but the overalll effect more than makes up for it. the lighting is a bit flat for emphasizing the textures</td>', 'really nice shot. colors are strong, focus very good and composition interesting. the oof part up-per right is slightly distracting, but the overalll effect more than makes up for it. the lighting is a bit flat for emphasizing the textures', '2005-07-20 19:29:49.000000', NULL, 1),
(1551250, 205699, 27158, '<td valign="top">this is wonderful! I love the textures and the story. the highlight area lower left is a bit distracting, but the wall more than makes up for it. great composition and the challenge is certainly met well. This is one of my favorites! bumping up</td>', 'this is wonderful! I love the textures and the story. the highlight area lower left is a bit distracting, but the wall more than makes up for it. great composition and the challenge is certainly met well. This is one of my favorites! bumping up', '2005-07-20 19:31:43.000000', NULL, 1),
(1551255, 206053, 27158, '<td valign="top">interesting photograph, but I fail to see an emphasis on texture. focus is good and exposure is ok, though the flame is a bit burned out. colors seem a bit bland.</td>', 'interesting photograph, but I fail to see an emphasis on texture. focus is good and exposure is ok, though the flame is a bit burned out. colors seem a bit bland.', '2005-07-20 19:33:32.000000', NULL, 1),
(1551257, 206145, 27158, '<td valign="top">cute and nice high key shot.</td>', 'cute and nice high key shot.', '2005-07-20 19:34:27.000000', NULL, 1),
(1551263, 206401, 27158, '<td valign="top">this seems a bit oversaturated and soft focus. nice textures...highlights blown and contrasty. has potential</td>', 'this seems a bit oversaturated and soft focus. nice textures...highlights blown and contrasty. has potential', '2005-07-20 19:36:26.000000', NULL, 1),
(1551264, 206479, 23653, '<td valign="top">Great idea, How did you set this up?....Decided to bumb to a 10 after seeing again, good luck.<br/> <br/>Ty</td>', 'Great idea, How did you set this up?....Decided to bumb to a 10 after seeing again, good luck. Ty', '2005-07-20 19:36:31.000000', NULL, 1),
(1551265, 205928, 27158, '<td valign="top">good texture...focus is lacking - perhaps a smaller aperture would have helped?</td>', 'good texture...focus is lacking - perhaps a smaller aperture would have helped?', '2005-07-20 19:37:49.000000', NULL, 1),
(1551268, 206393, 27158, '<td valign="top">for the challenge, the emotion of feeling a texture doesn''t substitute for the actual texture(s) imo. nice moody lighting and the softness works, as well as the b/w.</td>', 'for the challenge, the emotion of feeling a texture doesn''t substitute for the actual texture(s) imo. nice moody lighting and the softness works, as well as the b/w.', '2005-07-20 19:40:14.000000', NULL, 1),
(1551272, 206239, 27158, '<td valign="top">too small to evaluate. seems out of focus, and texture seems lacking. subject indifferent and title spelled wrong?</td>', 'too small to evaluate. seems out of focus, and texture seems lacking. subject indifferent and title spelled wrong?', '2005-07-20 19:43:06.000000', NULL, 1),
(1551276, 205062, 27158, '<td valign="top">nice textures here, though the composition si a bit weak, imo...seems top heavy and the very bright background detracts. perhaps a kick up in saturation and a bit less exposure would help. concentrating on the center part of the image and cropping the rest would make this better, i thknk.</td>', 'nice textures here, though the composition si a bit weak, imo...seems top heavy and the very bright background detracts. perhaps a kick up in saturation and a bit less exposure would help. concentrating on the center part of the image and cropping the rest would make this better, i thknk.', '2005-07-20 19:45:37.000000', NULL, 1),
(1551279, 205769, 27158, '<td valign="top">this has a lot of potential. however, the soft-focused areas and the blown highlights detract from this otherwise interesting image...meets the challenge well</td>', 'this has a lot of potential. however, the soft-focused areas and the blown highlights detract from this otherwise interesting image...meets the challenge well', '2005-07-20 19:47:41.000000', NULL, 1),
(1551280, 205016, 30669, '<td valign="top">Very nice</td>', 'Very nice', '2005-07-20 19:48:03.000000', NULL, 1),
(1551285, 206131, 27158, '<td valign="top">this tells a real story and is quite touching. lighting a bit harsh and composition a bit weak. hope the little one is doing well!</td>', 'this tells a real story and is quite touching. lighting a bit harsh and composition a bit weak. hope the little one is doing well!', '2005-07-20 19:50:24.000000', NULL, 1),
(1551286, 206559, 35034, '<td valign="top">This is a great shot, but TEXTURE?  That''s stretching the topic a bit!  Anyway, a lovely shot with nice color, composition, and general overall pizazz.</td>', 'This is a great shot, but TEXTURE?  That''s stretching the topic a bit!  Anyway, a lovely shot with nice color, composition, and general overall pizazz.', '2005-07-20 19:51:22.000000', NULL, 1),
(1551287, 204145, 27158, '<td valign="top">very colorful image...even a bit oversaturated. I would have liked the lighting more from the side to emphasize the textures, which are a bit obscured here. a bit too much contrast and the dark area on the top  unbalances the image.</td>', 'very colorful image...even a bit oversaturated. I would have liked the lighting more from the side to emphasize the textures, which are a bit obscured here. a bit too much contrast and the dark area on the top  unbalances the image.', '2005-07-20 19:52:38.000000', NULL, 1),
(1551288, 206169, 40370, '<td valign="top">I am voting  tough on this one because I photographed about 30 lichen and moss covered rocks and they didn''t evoke texture with light and shadow qualities, they were more about color qualities.</td>', 'I am voting  tough on this one because I photographed about 30 lichen and moss covered rocks and they didn''t evoke texture with light and shadow qualities, they were more about color qualities.', '2005-07-20 19:53:29.000000', NULL, 1),
(1551290, 205932, 27158, '<td valign="top">nice textures, but the blown highlights really weaken this shot.</td>', 'nice textures, but the blown highlights really weaken this shot.', '2005-07-20 19:54:21.000000', NULL, 1),
(1551292, 203696, 6532, '<td valign="top">I really like the picture.  The border is another thing - even though I generally favore borders, I think this one is a bit too thick.  Still good enough to earn you a 7</td>', 'I really like the picture.  The border is another thing - even though I generally favore borders, I think this one is a bit too thick.  Still good enough to earn you a 7', '2005-07-20 19:55:52.000000', NULL, 1),
(1551296, 206428, 40370, '<td valign="top">Looks like possible color adjustment lessened the texture effect.</td>', 'Looks like possible color adjustment lessened the texture effect.', '2005-07-20 19:56:32.000000', NULL, 1),
(1551302, 206578, 27158, '<td valign="top">nice exposure and focus. the composition seems a bit static and the textures are not really emphasized. perhaps a different angle might have worked?</td>', 'nice exposure and focus. the composition seems a bit static and the textures are not really emphasized. perhaps a different angle might have worked?', '2005-07-20 19:59:06.000000', NULL, 1),
(1551304, 206034, 24073, '<td valign="top">I like this photo, you did well.  I would really like to know how you got this overtone, this color this mood.  I have seen other photographers do it, and I am pretty good post processing, still I dont know how ya''ll are coming up with it.</td>', 'I like this photo, you did well.  I would really like to know how you got this overtone, this color this mood.  I have seen other photographers do it, and I am pretty good post processing, still I dont know how ya''ll are coming up with it.', '2005-07-20 19:59:35.000000', NULL, 1),
(1551305, 205918, 40370, '<td valign="top">Nice foreground, the sunset clouds don''t hurt either, too bad the light posts distract.</td>', 'Nice foreground, the sunset clouds don''t hurt either, too bad the light posts distract.', '2005-07-20 19:59:38.000000', NULL, 1),
(1551307, 205236, 27158, '<td valign="top">I''m not too nuts about the centered image here which really seems to emphasize the parts of the photo that shouldn''t be. Nice exposure though. the soft look would have worked better without the sharper seeds to the left.</td>', 'I''m not too nuts about the centered image here which really seems to emphasize the parts of the photo that shouldn''t be. Nice exposure though. the soft look would have worked better without the sharper seeds to the left.', '2005-07-20 20:01:15.000000', NULL, 1),
(1551308, 205909, 40370, '<td valign="top">B &amp; W was the only way too go on this one, you have to hunt for the textures but soon they are popping out at you.</td>', 'B & W was the only way too go on this one, you have to hunt for the textures but soon they are popping out at you.', '2005-07-20 20:01:25.000000', NULL, 1),
(1551311, 205894, 30669, '<td valign="top">Perfect for this challenge.</td>', 'Perfect for this challenge.', '2005-07-20 20:02:09.000000', NULL, 1),
(1551312, 206428, 33560, '<td valign="top">Love the texture of the skin, but I do wish we could see the elephant''s eye a little better...</td>', 'Love the texture of the skin, but I do wish we could see the elephant''s eye a little better...', '2005-07-20 20:03:02.000000', NULL, 1),
(1551314, 203752, 39684, '<td valign="top">WOW! What a great photo!   Very sharp and you definately can feel the texture. I gave you my first "10" ever.</td>', 'WOW! What a great photo!   Very sharp and you definately can feel the texture. I gave you my first "10" ever.', '2005-07-20 20:03:26.000000', NULL, 1),
(1551317, 205940, 33560, '<td valign="top">Might be a little more fun if more were in focus.</td>', 'Might be a little more fun if more were in focus.', '2005-07-20 20:04:05.000000', NULL, 1),
(1551319, 205324, 39684, '<td valign="top">Beautiful color! Great shot!</td>', 'Beautiful color! Great shot!', '2005-07-20 20:04:55.000000', NULL, 1),
(1551328, 206033, 37320, '<td valign="top">Im "feeling" it.  hahaha good shot/bad pun.</td>', 'Im "feeling" it.  hahaha good shot/bad pun.', '2005-07-20 20:12:34.000000', NULL, 1),
(1551332, 204495, 37320, '<td valign="top">Intresting choice of texture, your background is good but I would have liked to see something like a black background to make the title work better.  Good shot overall!</td>', 'Intresting choice of texture, your background is good but I would have liked to see something like a black background to make the title work better.  Good shot overall!', '2005-07-20 20:13:47.000000', NULL, 1),
(1551337, 205627, 37320, '<td valign="top">Really ugly, but in a really artistic way which I believe cancels it out and makes the photo all that much more impressive, I also enjoyed the variety of colors included in the palate.</td>', 'Really ugly, but in a really artistic way which I believe cancels it out and makes the photo all that much more impressive, I also enjoyed the variety of colors included in the palate.', '2005-07-20 20:15:54.000000', NULL, 1),
(1551339, 204836, 37320, '<td valign="top">I never realized how ugly an elephant''s posterior really is.  Ugly, but nevertheless an interesting and well captured texture.</td>', 'I never realized how ugly an elephant''s posterior really is.  Ugly, but nevertheless an interesting and well captured texture.', '2005-07-20 20:16:59.000000', NULL, 1),
(1551340, 206147, 37320, '<td valign="top">I tend not to enjoy the texture of babies, but you''re the artist not me.  Good lighting.</td>', 'I tend not to enjoy the texture of babies, but you''re the artist not me.  Good lighting.', '2005-07-20 20:18:38.000000', NULL, 1),
(1551342, 206031, 37320, '<td valign="top">This site has a lot of people who are really good at photographing palms of hands, I think you talented folk are ready to start a new field of photography!  Think about it!  You could do palm-portraits of rich people (maybe their pets too if they''re really rich)  Why you could even do candid palm shots, or palm landscapes!  Dont waste your talent get started today!!</td>', 'This site has a lot of people who are really good at photographing palms of hands, I think you talented folk are ready to start a new field of photography!  Think about it!  You could do palm-portraits of rich people (maybe their pets too if they''re really rich)  Why you could even do candid palm shots, or palm landscapes!  Dont waste your talent get started today!!', '2005-07-20 20:21:02.000000', NULL, 1),
(1551343, 206422, 37320, '<td valign="top">Isnt too much to say aside from that this picture is really good.</td>', 'Isnt too much to say aside from that this picture is really good.', '2005-07-20 20:21:51.000000', NULL, 1),
(1551345, 203538, 37320, '<td valign="top">Seaglass actually looks kinda tasty, I really should stop rating pictures hungry though.  Good luck.</td>', 'Seaglass actually looks kinda tasty, I really should stop rating pictures hungry though.  Good luck.', '2005-07-20 20:22:34.000000', NULL, 1),
(1551347, 205706, 28750, '<td valign="top">I think it would be much better if it has litle more contrast</td>', 'I think it would be much better if it has litle more contrast', '2005-07-20 20:22:53.000000', NULL, 1),
