(1552950, 206390, 40386, '<td valign="top">The detail is amazing, makes you want to reach out and touch it!</td>', 'The detail is amazing, makes you want to reach out and touch it!', '2005-07-21 15:27:34.000000', NULL, 1),
(1552952, 206468, 40386, '<td valign="top">Great shot, so many different textures all in one.</td>', 'Great shot, so many different textures all in one.', '2005-07-21 15:29:40.000000', NULL, 1),
