(1552955, 205030, 40386, '<td valign="top">Lovely shot!! Makes you want to eat it. Beautiful color</td>', 'Lovely shot!! Makes you want to eat it. Beautiful color', '2005-07-21 15:31:37.000000', NULL, 1),
(1552957, 206559, 40386, '<td valign="top">Wow this is stunning, colors and sharpness are beautiful</td>', 'Wow this is stunning, colors and sharpness are beautiful', '2005-07-21 15:32:14.000000', NULL, 1),
(1552960, 204541, 40386, '<td valign="top">Wonderful shot, well captured and thought out.  The only thing I would change is to take a bit of the black area at the bottom of the frame out but thats just me LOL</td>', 'Wonderful shot, well captured and thought out.  The only thing I would change is to take a bit of the black area at the bottom of the frame out but thats just me LOL', '2005-07-21 15:33:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1552961, 205765, 39111, '<td valign="top">really pretty.  not feeling a lot of texture here, though.</td>', 'really pretty.  not feeling a lot of texture here, though.', '2005-07-21 15:33:46.000000', NULL, 1),
(1552962, 206412, 40386, '<td valign="top">This makes me laugh, nice combination of textures and colors</td>', 'This makes me laugh, nice combination of textures and colors', '2005-07-21 15:34:09.000000', NULL, 1),
(1552967, 204245, 40386, '<td valign="top">Great focus and exposure</td>', 'Great focus and exposure', '2005-07-21 15:39:13.000000', NULL, 1),
(1552971, 204987, 40386, '<td valign="top">This would have been a better shot if you had had a point of focus, maybe something on the window sill to give the shot a bit more interest</td>', 'This would have been a better shot if you had had a point of focus, maybe something on the window sill to give the shot a bit more interest', '2005-07-21 15:41:51.000000', NULL, 1),
(1552972, 205986, 40386, '<td valign="top">Picture is a bit small to really evaluate properly, cant decide if it has a point that is properly in focus or not.</td>', 'Picture is a bit small to really evaluate properly, cant decide if it has a point that is properly in focus or not.', '2005-07-21 15:44:18.000000', NULL, 1),
(1552974, 205595, 40386, '<td valign="top">This shot could be a little less bright, it appears overexposed which washes out the colors, the hot spots spoil it for me too</td>', 'This shot could be a little less bright, it appears overexposed which washes out the colors, the hot spots spoil it for me too', '2005-07-21 15:45:49.000000', NULL, 1),
(1552977, 205979, 40386, '<td valign="top">The highlights are a bit too extreme for me</td>', 'The highlights are a bit too extreme for me', '2005-07-21 15:47:30.000000', NULL, 1),
(1553007, 206376, 31443, '<td valign="top">I like the atmosphere here but am wondering if you left the egg out of focus on purpose..</td>', 'I like the atmosphere here but am wondering if you left the egg out of focus on purpose..', '2005-07-21 16:16:19.000000', NULL, 1),
(1553025, 206557, 31443, '<td valign="top">Going for the yellow? Cute..</td>', 'Going for the yellow? Cute..', '2005-07-21 16:26:02.000000', NULL, 1),
(1553032, 206131, 37529, '<td valign="top">This photo is hauting me, I want to know what happens with this little guy!</td>', 'This photo is hauting me, I want to know what happens with this little guy!', '2005-07-21 16:32:03.000000', NULL, 1),
(1553034, 205730, 37529, '<td valign="top">Reminds me of a Maxfield Parrish drawing, very pleasent place!</td>', 'Reminds me of a Maxfield Parrish drawing, very pleasent place!', '2005-07-21 16:33:06.000000', NULL, 1),
(1553037, 204188, 37529, '<td valign="top">What a great face!</td>', 'What a great face!', '2005-07-21 16:33:48.000000', NULL, 1),
(1553038, 206336, 37529, '<td valign="top">Wonderful shot, very moody and the color is perfect.</td>', 'Wonderful shot, very moody and the color is perfect.', '2005-07-21 16:35:05.000000', NULL, 1),
(1553040, 206381, 4477, '<td valign="top">Very original.  You can actually see the texture of the paper.  Great job!</td>', 'Very original.  You can actually see the texture of the paper.  Great job!', '2005-07-21 16:36:31.000000', NULL, 1),
(1553042, 206579, 4477, '<td valign="top">The use of lighting and shadows in this photo are just amazing!  Great!</td>', 'The use of lighting and shadows in this photo are just amazing!  Great!', '2005-07-21 16:37:18.000000', NULL, 1),
(1553044, 206130, 30061, '<td valign="top">Gorgeous color.  Love the water drops and the angle of the leaf.  The edge seems slightly overexposed against the black background, but overall, it''s beautiful! Nicely done. 8</td>', 'Gorgeous color.  Love the water drops and the angle of the leaf.  The edge seems slightly overexposed against the black background, but overall, it''s beautiful! Nicely done. 8', '2005-07-21 16:38:40.000000', NULL, 1),
(1553047, 206024, 30061, '<td valign="top">Wow, that''s a pretty cool macro.  I wish the tips of the wings weren''t cut off, though.  Cool shot!</td>', 'Wow, that''s a pretty cool macro.  I wish the tips of the wings weren''t cut off, though.  Cool shot!', '2005-07-21 16:39:37.000000', NULL, 1),
(1553054, 203538, 37234, '<td valign="top">Sea glass is cool! Interesting idea, well executed.</td>', 'Sea glass is cool! Interesting idea, well executed.', '2005-07-21 16:50:55.000000', NULL, 1),
(1553058, 204909, 37234, '<td valign="top">Interesting title. Makes the viewer take a second look and think about the photo. Well done compositionally. I like the vantage point.</td>', 'Interesting title. Makes the viewer take a second look and think about the photo. Well done compositionally. I like the vantage point.', '2005-07-21 16:54:16.000000', NULL, 1),
(1553059, 205199, 34058, '<td valign="top">This is such a beautiful shot!  They look so fuzzy!</td>', 'This is such a beautiful shot!  They look so fuzzy!', '2005-07-21 16:54:18.000000', NULL, 1),
(1553061, 204446, 34058, '<td valign="top">He is sooooo cute!  I would love to touch him!!!  Look at that face:)</td>', 'He is sooooo cute!  I would love to touch him!!!  Look at that face:)', '2005-07-21 16:55:29.000000', NULL, 1),
(1553063, 204583, 34058, '<td valign="top">This is such a cool idea, I just think it would have been better if the candle holes weren''t there.  But I like it!</td>', 'This is such a cool idea, I just think it would have been better if the candle holes weren''t there.  But I like it!', '2005-07-21 16:56:46.000000', NULL, 1),
(1553064, 206465, 37234, '<td valign="top">Very interesting. I realize that shadows don''t really count as texture, but the illusion of texture is there. I think this picture would be nearly perfect with a couple minor tweaks: crop the right and left sides in a bit to get rid fo the line in the top right corner (but retain symmetry), and desaturate with levels adjustment to boost the shadows.</td>', 'Very interesting. I realize that shadows don''t really count as texture, but the illusion of texture is there. I think this picture would be nearly perfect with a couple minor tweaks: crop the right and left sides in a bit to get rid fo the line in the top right corner (but retain symmetry), and desaturate with levels adjustment to boost the shadows.', '2005-07-21 16:57:16.000000', NULL, 1),
(1553065, 204775, 37234, '<td valign="top">Certainly "textury", to coin a word. Kinda gross, though ;-)</td>', 'Certainly "textury", to coin a word. Kinda gross, though ;-)', '2005-07-21 16:57:44.000000', NULL, 1),
(1553067, 205332, 37234, '<td valign="top">Underexposed, IMO</td>', 'Underexposed, IMO', '2005-07-21 16:58:10.000000', NULL, 1),
(1553068, 204947, 37234, '<td valign="top">Cute. One of the more original shots in this challenge. I think your DOF could have been a bit longer to include more of the carpet.</td>', 'Cute. One of the more original shots in this challenge. I think your DOF could have been a bit longer to include more of the carpet.', '2005-07-21 16:58:58.000000', NULL, 1),
(1553070, 205730, 37234, '<td valign="top">Very pretty. I see this as having a lot more impact as a B&amp;W. Clarity &amp; focus is good. A touch overexposed on the cloud, but nothing horrible. I think the most immediate detraction is probably the green cast. Once again, B&amp;W would solve that and, IMO, give the photo more impact.</td>', 'Very pretty. I see this as having a lot more impact as a B&W. Clarity & focus is good. A touch overexposed on the cloud, but nothing horrible. I think the most immediate detraction is probably the green cast. Once again, B&W would solve that and, IMO, give the photo more impact.', '2005-07-21 17:00:23.000000', NULL, 1),
(1553076, 206024, 37234, '<td valign="top">Heh. Nice title. Looks to me like he(she?) has plenty of texture. Not that I''d want to pet him to test. Maybe a touch more DOF would give more clarity to the head and tail areas?</td>', 'Heh. Nice title. Looks to me like he(she?) has plenty of texture. Not that I''d want to pet him to test. Maybe a touch more DOF would give more clarity to the head and tail areas?', '2005-07-21 17:01:49.000000', NULL, 1),
(1553078, 205107, 37234, '<td valign="top">This is nice. A touch underexposed, perhaps, but that may have been an artistic choice? I wonder what this would look like in B&amp;W? The "spots" on the bottom right black area are distractions.</td>', 'This is nice. A touch underexposed, perhaps, but that may have been an artistic choice? I wonder what this would look like in B&W? The "spots" on the bottom right black area are distractions.', '2005-07-21 17:02:44.000000', NULL, 1),
(1553081, 206335, 37234, '<td valign="top">Probably the best done fruit image in this challenge. Nice color, choice of attractive specimens, color, clarity, etc.</td>', 'Probably the best done fruit image in this challenge. Nice color, choice of attractive specimens, color, clarity, etc.', '2005-07-21 17:03:49.000000', NULL, 1),
(1553086, 206302, 37234, '<td valign="top">Cute title. There''s something "off" here, and I can''t put my finger on it. Focus, maybe? It seems like there''s something missing, and it may be a need for a touch more sharpness in the front. Not quite sure. Nice choice of B&amp;W colorization.</td>', 'Cute title. There''s something "off" here, and I can''t put my finger on it. Focus, maybe? It seems like there''s something missing, and it may be a need for a touch more sharpness in the front. Not quite sure. Nice choice of B&W colorization.', '2005-07-21 17:05:34.000000', NULL, 1),
(1553090, 205871, 37234, '<td valign="top">Candid? Please PM me with the answer, if you are comfortable doing so during a challenge. The answer will affect the way I vote.</td>', 'Candid? Please PM me with the answer, if you are comfortable doing so during a challenge. The answer will affect the way I vote.', '2005-07-21 17:07:06.000000', NULL, 1),
(1553095, 206237, 37234, '<td valign="top">That is too funny. Crunch, crunch!</td>', 'That is too funny. Crunch, crunch!', '2005-07-21 17:08:35.000000', NULL, 1),
(1553100, 205996, 40371, '<td valign="top">Nice caption</td>', 'Nice caption', '2005-07-21 17:12:09.000000', NULL, 1),
(1553101, 205211, 37234, '<td valign="top">Haha, I''ll bet you''ve gotten a lot of comments from confused voters. Great title (I''m assuming it''s a joke and not a mistake, here)!<br/> <br/>By the way, you should keep your dog out of the sun. Either that or start giving him/her some sunblock.</td>', 'Haha, I''ll bet you''ve gotten a lot of comments from confused voters. Great title (I''m assuming it''s a joke and not a mistake, here)! By the way, you should keep your dog out of the sun. Either that or start giving him/her some sunblock.', '2005-07-21 17:12:24.000000', NULL, 1),
(1553110, 206311, 40881, '<td valign="top">i think this is a bit too over exposed, there would have been a lot more visible texture if it was a bit darker, both in the fruit and the table.</td>', 'i think this is a bit too over exposed, there would have been a lot more visible texture if it was a bit darker, both in the fruit and the table.', '2005-07-21 17:15:38.000000', NULL, 1),
(1553119, 206223, 40881, '<td valign="top">good to see some nice strongly defined  texture, but I would have preferred to see it in colour</td>', 'good to see some nice strongly defined  texture, but I would have preferred to see it in colour', '2005-07-21 17:22:41.000000', NULL, 1),
(1553121, 205235, 38927, '<td valign="top">Very detailed in textured areas, good color and dof</td>', 'Very detailed in textured areas, good color and dof', '2005-07-21 17:23:41.000000', NULL, 1),
(1553122, 206088, 39265, '<td valign="top">I really like the textures and the colours. Great shot. Good Luck.</td>', 'I really like the textures and the colours. Great shot. Good Luck.', '2005-07-21 17:23:57.000000', NULL, 1),
(1553123, 206065, 39265, '<td valign="top">This is a cool shot. Good Luck!</td>', 'This is a cool shot. Good Luck!', '2005-07-21 17:24:38.000000', NULL, 1),
(1553126, 204145, 39265, '<td valign="top">I really like the sat. and colours. Good luck.</td>', 'I really like the sat. and colours. Good luck.', '2005-07-21 17:25:18.000000', NULL, 1),
(1553131, 205016, 39265, '<td valign="top">I really like the feel of this photo. She looks like she has had a hard and serious like. 10</td>', 'I really like the feel of this photo. She looks like she has had a hard and serious like. 10', '2005-07-21 17:29:05.000000', NULL, 1),
(1553138, 205632, 39265, '<td valign="top">I really like this shot. Good luck!</td>', 'I really like this shot. Good luck!', '2005-07-21 17:32:47.000000', NULL, 1),
(1553149, 203415, 39265, '<td valign="top">Pretty cool photo. Good Luck!</td>', 'Pretty cool photo. Good Luck!', '2005-07-21 17:45:17.000000', NULL, 1),
(1553151, 204105, 39265, '<td valign="top">I think it would have been a better photo without the dash and the right side of the car, but good photo otherwise. Good Luck.</td>', 'I think it would have been a better photo without the dash and the right side of the car, but good photo otherwise. Good Luck.', '2005-07-21 17:46:46.000000', NULL, 1),
(1553152, 203975, 25577, '<td valign="top">I would have liked to see this in the full 640, good color, good composition.</td>', 'I would have liked to see this in the full 640, good color, good composition.', '2005-07-21 17:47:05.000000', NULL, 1),
(1553153, 206016, 25577, '<td valign="top">nice selection for texture, the top left corner is creating static by catching the viewers eye while moving through the picture</td>', 'nice selection for texture, the top left corner is creating static by catching the viewers eye while moving through the picture', '2005-07-21 17:49:24.000000', NULL, 1),
(1553158, 204751, 23053, '<td valign="top">This is a good shot - let it speak for itself!  The title is patronizing, doubly so considering that the challenge already directs the viewer to look at textures.  I do think that you did a good job with your main objective in taking a shot that shows lots of good texture...so for that, good on you!</td>', 'This is a good shot - let it speak for itself!  The title is patronizing, doubly so considering that the challenge already directs the viewer to look at textures.  I do think that you did a good job with your main objective in taking a shot that shows lots of good texture...so for that, good on you!', '2005-07-21 18:02:35.000000', NULL, 1),
(1553159, 206561, 23053, '<td valign="top">Good use of black and white and an astounding amount of detail and texture.  This shot has a spooky feel to me, but I like it and I hope it does well.</td>', 'Good use of black and white and an astounding amount of detail and texture.  This shot has a spooky feel to me, but I like it and I hope it does well.', '2005-07-21 18:04:43.000000', NULL, 1),
(1553160, 204825, 19952, '<td valign="top">This is an absolutely gorgeous shot. I don''t think it has a terribly strong connection to the challenge, but that doesn''t keep this from being an outstanding photo with excellent tonal range, lighting and composition. Very nicely done.</td>', 'This is an absolutely gorgeous shot. I don''t think it has a terribly strong connection to the challenge, but that doesn''t keep this from being an outstanding photo with excellent tonal range, lighting and composition. Very nicely done.', '2005-07-21 18:05:11.000000', NULL, 1),
(1553161, 206053, 30061, '<td valign="top">I feel certain that you must have intended some symbolism or deep meaning here that I must be missing.  Also, I don''t see much that would count as texture, save for the can, but even it seems to be more dirty than textured.</td>', 'I feel certain that you must have intended some symbolism or deep meaning here that I must be missing.  Also, I don''t see much that would count as texture, save for the can, but even it seems to be more dirty than textured.', '2005-07-21 18:05:50.000000', NULL, 1),
(1553162, 206031, 7743, '<td valign="top">What works: the diagonal placement of the hand and the lighting of the part of the palm just below the fingers.<br/> <br/>What doesn''t seem to work: DOF seems a bit shallow. Seems a bit underexposed despite a couple of hot spots.  The corners are a bit dark.  It could be that it is too much of a closeup.</td>', 'What works: the diagonal placement of the hand and the lighting of the part of the palm just below the fingers. What doesn''t seem to work: DOF seems a bit shallow. Seems a bit underexposed despite a couple of hot spots.  The corners are a bit dark.  It could be that it is too much of a closeup.', '2005-07-21 18:06:37.000000', NULL, 1),
(1553163, 206301, 40669, '<td valign="top">Very interesting texture.  I really love the upper left area - the sharpness and the light on that section is beautiful, but the lower right darkness and fuzziness is a little bothersome.  I think cropping and coming in closer could really make a difference.</td>', 'Very interesting texture.  I really love the upper left area - the sharpness and the light on that section is beautiful, but the lower right darkness and fuzziness is a little bothersome.  I think cropping and coming in closer could really make a difference.', '2005-07-21 18:06:44.000000', NULL, 1),
(1553164, 205983, 30061, '<td valign="top">This is a nice, clear shot, but it doesn''t seem to have much interest for me. 6</td>', 'This is a nice, clear shot, but it doesn''t seem to have much interest for me. 6', '2005-07-21 18:07:06.000000', NULL, 1),
(1553166, 205699, 19952, '<td valign="top">Wow! Great textures, great composition, great processing. You did an amazing  job making an outstanding composition out of a simple and unlikely subject.</td>', 'Wow! Great textures, great composition, great processing. You did an amazing  job making an outstanding composition out of a simple and unlikely subject.', '2005-07-21 18:08:16.000000', NULL, 1),
(1553167, 206218, 30061, '<td valign="top">Looks nice and soft. :)</td>', 'Looks nice and soft. :)', '2005-07-21 18:08:39.000000', NULL, 1),
(1553170, 206176, 30061, '<td valign="top">Nice composition and choice of black &amp; white.  The subject seems a little obvious for the challenge, though.  7</td>', 'Nice composition and choice of black & white.  The subject seems a little obvious for the challenge, though.  7', '2005-07-21 18:09:31.000000', NULL, 1),
(1553171, 203692, 30061, '<td valign="top">Awesome!  This is the first shot I''ve seen so far that just struck me as "Wow!"  The sharpness is incredible.  10</td>', 'Awesome!  This is the first shot I''ve seen so far that just struck me as "Wow!"  The sharpness is incredible.  10', '2005-07-21 18:11:54.000000', NULL, 1),
(1553173, 204906, 10848, '<td valign="top">Wow, what a face!! Outstanding capture, wonderful color and detail, and definite textures to that skin! Good Luck! 10</td>', 'Wow, what a face!! Outstanding capture, wonderful color and detail, and definite textures to that skin! Good Luck! 10', '2005-07-21 18:13:25.000000', NULL, 1),
(1553175, 206404, 30061, '<td valign="top">Great silhouette.  The overexposed parts of the water can be a little harsh, but the right side of the shot makes up for it.</td>', 'Great silhouette.  The overexposed parts of the water can be a little harsh, but the right side of the shot makes up for it.', '2005-07-21 18:13:38.000000', NULL, 1),
