(1556476, 204443, 7304, '<td valign="top">Excellent capture. The fly too. Aged leathery look.</td>', 'Excellent capture. The fly too. Aged leathery look.', '2005-07-23 02:13:29.000000', NULL, 1),
(1556479, 206518, 7304, '<td valign="top">Weird but cool shot. Plenty of texture here.</td>', 'Weird but cool shot. Plenty of texture here.', '2005-07-23 02:15:17.000000', NULL, 1),
(1556481, 204556, 7304, '<td valign="top">Nice texture of the lips. I would have liked to see some more of the red pop off the image.</td>', 'Nice texture of the lips. I would have liked to see some more of the red pop off the image.', '2005-07-23 02:16:25.000000', NULL, 1),
(1556482, 206574, 36462, '<td valign="top">All the blue at the top is a bit distracting.  Cropping the water out, up to the top of the rock/boulder brings the eye more to the carving.  7</td>', 'All the blue at the top is a bit distracting.  Cropping the water out, up to the top of the rock/boulder brings the eye more to the carving.  7', '2005-07-23 02:17:02.000000', NULL, 1),
