(1564763, 205699, 35161, '<td valign="top">Love the textures in the background! Nice tones! :)</td>', 'Love the textures in the background! Nice tones! :)', '2005-07-26 19:09:07.000000', NULL, 1),
(1564764, 205319, 35161, '<td valign="top">Very nice capture! :)</td>', 'Very nice capture! :)', '2005-07-26 19:09:42.000000', NULL, 1),
